-- Grace initial schema, version 1 (sqlite). Generated by npm run db:schema.
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS schema_migrations (
  version INTEGER PRIMARY KEY,
  applied_at VARCHAR(32) NOT NULL
);

CREATE TABLE IF NOT EXISTS workspaces (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  slug VARCHAR(120) NOT NULL UNIQUE,
  created_at VARCHAR(32) NOT NULL
);

CREATE TABLE IF NOT EXISTS users (
  id VARCHAR(64) PRIMARY KEY,
  email VARCHAR(254) NOT NULL UNIQUE,
  name VARCHAR(120) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  color VARCHAR(20) NOT NULL,
  capacity INTEGER NOT NULL DEFAULT 40,
  created_at VARCHAR(32) NOT NULL
);

CREATE TABLE IF NOT EXISTS memberships (
  workspace_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  role VARCHAR(20) NOT NULL,
  PRIMARY KEY (workspace_id,user_id),
  FOREIGN KEY (workspace_id) REFERENCES workspaces(id),
  FOREIGN KEY (user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS sessions (
  id VARCHAR(64) PRIMARY KEY,
  user_id VARCHAR(64) NOT NULL,
  workspace_id VARCHAR(64) NOT NULL,
  refresh_hash VARCHAR(128) NOT NULL UNIQUE,
  expires_at VARCHAR(32) NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id),
  FOREIGN KEY (workspace_id) REFERENCES workspaces(id)
);

CREATE TABLE IF NOT EXISTS invites (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  email VARCHAR(254) NOT NULL,
  role VARCHAR(20) NOT NULL,
  token_hash VARCHAR(128) NOT NULL UNIQUE,
  expires_at VARCHAR(32) NOT NULL,
  accepted_at VARCHAR(32),
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(workspace_id) REFERENCES workspaces(id)
);

CREATE TABLE IF NOT EXISTS projects (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  name VARCHAR(120) NOT NULL,
  `key` VARCHAR(10) NOT NULL,
  description TEXT NOT NULL,
  color VARCHAR(20) NOT NULL,
  icon VARCHAR(30) NOT NULL,
  lead_id VARCHAR(64) NOT NULL,
  template VARCHAR(20) NOT NULL,
  visibility VARCHAR(20) NOT NULL DEFAULT 'workspace',
  favorite INTEGER NOT NULL DEFAULT 0,
  next_number INTEGER NOT NULL DEFAULT 1,
  archived_at VARCHAR(32),
  created_at VARCHAR(32) NOT NULL,
  UNIQUE(workspace_id,`key`),
  FOREIGN KEY (workspace_id) REFERENCES workspaces(id),
  FOREIGN KEY (lead_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS project_members (
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  role VARCHAR(20) NOT NULL,
  PRIMARY KEY(project_id,user_id),
  FOREIGN KEY(project_id) REFERENCES projects(id),
  FOREIGN KEY(user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS statuses (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64) NOT NULL,
  name VARCHAR(80) NOT NULL,
  category VARCHAR(20) NOT NULL,
  color VARCHAR(20) NOT NULL,
  position INTEGER NOT NULL,
  wip_limit INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (project_id) REFERENCES projects(id)
);

CREATE TABLE IF NOT EXISTS sprints (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64) NOT NULL,
  name VARCHAR(120) NOT NULL,
  goal TEXT NOT NULL,
  state VARCHAR(20) NOT NULL,
  start_date VARCHAR(32) NOT NULL,
  end_date VARCHAR(32) NOT NULL,
  committed_points INTEGER NOT NULL DEFAULT 0,
  completed_points INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY(project_id) REFERENCES projects(id)
);

CREATE TABLE IF NOT EXISTS issues (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64) NOT NULL,
  number INTEGER NOT NULL,
  `key` VARCHAR(32) NOT NULL,
  summary VARCHAR(255) NOT NULL,
  description TEXT NOT NULL,
  type VARCHAR(20) NOT NULL,
  status_id VARCHAR(64) NOT NULL,
  priority VARCHAR(20) NOT NULL,
  assignee_id VARCHAR(64),
  reporter_id VARCHAR(64) NOT NULL,
  parent_id VARCHAR(64),
  sprint_id VARCHAR(64),
  labels TEXT NOT NULL,
  story_points INTEGER NOT NULL DEFAULT 0,
  due_date VARCHAR(32) NOT NULL,
  start_date VARCHAR(32) NOT NULL,
  `rank` REAL NOT NULL,
  flagged INTEGER NOT NULL DEFAULT 0,
  carry_over INTEGER NOT NULL DEFAULT 0,
  version INTEGER NOT NULL DEFAULT 1,
  created_at VARCHAR(32) NOT NULL,
  updated_at VARCHAR(32) NOT NULL,
  deleted_at VARCHAR(32),
  UNIQUE(project_id,number),
  UNIQUE(workspace_id,`key`),
  FOREIGN KEY (project_id) REFERENCES projects(id),
  FOREIGN KEY(status_id) REFERENCES statuses(id),
  FOREIGN KEY(assignee_id) REFERENCES users(id),
  FOREIGN KEY(reporter_id) REFERENCES users(id),
  FOREIGN KEY(parent_id) REFERENCES issues(id),
  FOREIGN KEY(sprint_id) REFERENCES sprints(id)
);

CREATE TABLE IF NOT EXISTS comments (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  author_id VARCHAR(64) NOT NULL,
  body TEXT NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  edited_at VARCHAR(32),
  FOREIGN KEY(issue_id) REFERENCES issues(id),
  FOREIGN KEY(author_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS history (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  actor_id VARCHAR(64) NOT NULL,
  field VARCHAR(80) NOT NULL,
  old_value TEXT NOT NULL,
  new_value TEXT NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(issue_id) REFERENCES issues(id),
  FOREIGN KEY(actor_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS worklogs (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  minutes INTEGER NOT NULL,
  note TEXT NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(issue_id) REFERENCES issues(id),
  FOREIGN KEY(user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS attachments (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  uploader_id VARCHAR(64) NOT NULL,
  name VARCHAR(255) NOT NULL,
  path VARCHAR(128) NOT NULL,
  mime VARCHAR(120) NOT NULL,
  size INTEGER NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(issue_id) REFERENCES issues(id)
);

CREATE TABLE IF NOT EXISTS issue_links (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  source_id VARCHAR(64) NOT NULL,
  target_id VARCHAR(64) NOT NULL,
  type VARCHAR(30) NOT NULL,
  UNIQUE(source_id,target_id,type),
  FOREIGN KEY(source_id) REFERENCES issues(id),
  FOREIGN KEY(target_id) REFERENCES issues(id)
);

CREATE TABLE IF NOT EXISTS watchers (
  workspace_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  PRIMARY KEY(issue_id,user_id),
  FOREIGN KEY(issue_id) REFERENCES issues(id),
  FOREIGN KEY(user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS notifications (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64),
  title VARCHAR(255) NOT NULL,
  body TEXT NOT NULL,
  read_at VARCHAR(32),
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS pages (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64),
  title VARCHAR(255) NOT NULL,
  content TEXT NOT NULL,
  icon VARCHAR(30) NOT NULL,
  author_id VARCHAR(64) NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  updated_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(project_id) REFERENCES projects(id),
  FOREIGN KEY(author_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS page_versions (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  page_id VARCHAR(64) NOT NULL,
  title VARCHAR(255) NOT NULL,
  content TEXT NOT NULL,
  version INTEGER NOT NULL,
  author_id VARCHAR(64) NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(page_id) REFERENCES pages(id)
);

CREATE TABLE IF NOT EXISTS saved_views (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  name VARCHAR(120) NOT NULL,
  query TEXT NOT NULL,
  owner_id VARCHAR(64) NOT NULL,
  sharing VARCHAR(20) NOT NULL,
  FOREIGN KEY(owner_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS standups (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  yesterday TEXT NOT NULL,
  today TEXT NOT NULL,
  blockers TEXT NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS risks (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64),
  title VARCHAR(255) NOT NULL,
  severity VARCHAR(20) NOT NULL,
  state VARCHAR(20) NOT NULL,
  owner_id VARCHAR(64) NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(project_id) REFERENCES projects(id)
);

CREATE TABLE IF NOT EXISTS audit_log (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  actor_id VARCHAR(64) NOT NULL,
  action VARCHAR(80) NOT NULL,
  target_id VARCHAR(64) NOT NULL,
  detail TEXT NOT NULL,
  created_at VARCHAR(32) NOT NULL
);

CREATE TABLE IF NOT EXISTS project_modules (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64) NOT NULL,
  name VARCHAR(120) NOT NULL,
  description TEXT NOT NULL,
  lead_id VARCHAR(64),
  state VARCHAR(20) NOT NULL,
  start_date VARCHAR(32) NOT NULL,
  end_date VARCHAR(32) NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  archived_at VARCHAR(32),
  created_at VARCHAR(32) NOT NULL,
  updated_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(project_id) REFERENCES projects(id),
  FOREIGN KEY(lead_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS module_issues (
  workspace_id VARCHAR(64) NOT NULL,
  module_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  added_at VARCHAR(32) NOT NULL,
  PRIMARY KEY(module_id,issue_id),
  FOREIGN KEY(module_id) REFERENCES project_modules(id),
  FOREIGN KEY(issue_id) REFERENCES issues(id)
);

CREATE TABLE IF NOT EXISTS planning_baselines (
  issue_id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64) NOT NULL,
  sprint_id VARCHAR(64),
  status_id VARCHAR(64) NOT NULL,
  story_points INTEGER NOT NULL,
  deleted_at VARCHAR(32),
  recorded_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(issue_id) REFERENCES issues(id)
);

CREATE TABLE IF NOT EXISTS sprint_snapshots (
  sprint_id VARCHAR(64) NOT NULL,
  phase VARCHAR(10) NOT NULL,
  workspace_id VARCHAR(64) NOT NULL,
  total_issues INTEGER NOT NULL,
  completed_issues INTEGER NOT NULL,
  total_points INTEGER NOT NULL,
  completed_points INTEGER NOT NULL,
  recorded_at VARCHAR(32) NOT NULL,
  PRIMARY KEY(sprint_id,phase),
  FOREIGN KEY(sprint_id) REFERENCES sprints(id)
);

CREATE TABLE IF NOT EXISTS sprint_issue_snapshots (
  sprint_id VARCHAR(64) NOT NULL,
  phase VARCHAR(10) NOT NULL,
  workspace_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  issue_key VARCHAR(32) NOT NULL,
  summary VARCHAR(255) NOT NULL,
  status_id VARCHAR(64) NOT NULL,
  story_points INTEGER NOT NULL,
  category VARCHAR(20) NOT NULL,
  PRIMARY KEY(sprint_id,phase,issue_id),
  FOREIGN KEY(sprint_id) REFERENCES sprints(id),
  FOREIGN KEY(issue_id) REFERENCES issues(id)
);

CREATE TABLE IF NOT EXISTS module_members (
  module_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  workspace_id VARCHAR(64) NOT NULL,
  PRIMARY KEY(module_id,user_id),
  FOREIGN KEY(module_id) REFERENCES project_modules(id),
  FOREIGN KEY(user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS module_dependencies (
  module_id VARCHAR(64) NOT NULL,
  depends_on_id VARCHAR(64) NOT NULL,
  workspace_id VARCHAR(64) NOT NULL,
  PRIMARY KEY(module_id,depends_on_id),
  FOREIGN KEY(module_id) REFERENCES project_modules(id),
  FOREIGN KEY(depends_on_id) REFERENCES project_modules(id)
);

CREATE TABLE IF NOT EXISTS initiatives (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  name VARCHAR(160) NOT NULL,
  description TEXT NOT NULL,
  state VARCHAR(20) NOT NULL,
  lead_id VARCHAR(64),
  target_date VARCHAR(32) NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  created_by VARCHAR(64) NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  updated_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(workspace_id) REFERENCES workspaces(id),
  FOREIGN KEY(lead_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS initiative_modules (
  initiative_id VARCHAR(64) NOT NULL,
  module_id VARCHAR(64) NOT NULL,
  workspace_id VARCHAR(64) NOT NULL,
  PRIMARY KEY(initiative_id,module_id),
  FOREIGN KEY(initiative_id) REFERENCES initiatives(id),
  FOREIGN KEY(module_id) REFERENCES project_modules(id)
);

CREATE TABLE IF NOT EXISTS cycle_retrospectives (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  sprint_id VARCHAR(64) NOT NULL,
  author_id VARCHAR(64) NOT NULL,
  went_well TEXT NOT NULL,
  improve TEXT NOT NULL,
  actions TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  updated_at VARCHAR(32) NOT NULL,
  UNIQUE(sprint_id,author_id),
  FOREIGN KEY(sprint_id) REFERENCES sprints(id),
  FOREIGN KEY(author_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS account_security (
  user_id VARCHAR(64) PRIMARY KEY,
  verified_at VARCHAR(32),
  FOREIGN KEY(user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS account_tokens (
  id VARCHAR(64) PRIMARY KEY,
  user_id VARCHAR(64) NOT NULL,
  purpose VARCHAR(20) NOT NULL,
  token_hash VARCHAR(128) NOT NULL UNIQUE,
  expires_at VARCHAR(32) NOT NULL,
  consumed_at VARCHAR(32),
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS mail_deliveries (
  id VARCHAR(64) PRIMARY KEY,
  user_id VARCHAR(64) NOT NULL,
  kind VARCHAR(30) NOT NULL,
  state VARCHAR(20) NOT NULL,
  error_code VARCHAR(80) NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  updated_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS member_deactivations (
  workspace_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  actor_id VARCHAR(64) NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  PRIMARY KEY(workspace_id,user_id),
  FOREIGN KEY(workspace_id) REFERENCES workspaces(id),
  FOREIGN KEY(user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS notification_preferences (
  workspace_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  event VARCHAR(30) NOT NULL,
  in_app INTEGER NOT NULL,
  email INTEGER NOT NULL,
  PRIMARY KEY(workspace_id,user_id,event),
  FOREIGN KEY(user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS comment_mentions (
  workspace_id VARCHAR(64) NOT NULL,
  comment_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  PRIMARY KEY(comment_id,user_id),
  FOREIGN KEY(comment_id) REFERENCES comments(id),
  FOREIGN KEY(user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS issue_aliases (
  workspace_id VARCHAR(64) NOT NULL,
  alias_key VARCHAR(32) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  PRIMARY KEY(workspace_id,alias_key),
  FOREIGN KEY(issue_id) REFERENCES issues(id)
);

CREATE TABLE IF NOT EXISTS issue_templates (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64),
  name VARCHAR(120) NOT NULL,
  description TEXT NOT NULL,
  defaults_json TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  created_by VARCHAR(64) NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  updated_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(workspace_id) REFERENCES workspaces(id),
  FOREIGN KEY(project_id) REFERENCES projects(id)
);

CREATE TABLE IF NOT EXISTS project_configuration (
  project_id VARCHAR(64) PRIMARY KEY,
  issue_types TEXT NOT NULL,
  default_type VARCHAR(20) NOT NULL,
  cycles_enabled INTEGER NOT NULL,
  FOREIGN KEY(project_id) REFERENCES projects(id)
);

CREATE TABLE IF NOT EXISTS organization_teams (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  name VARCHAR(100) NOT NULL,
  slug VARCHAR(100) NOT NULL,
  description TEXT NOT NULL,
  color VARCHAR(20) NOT NULL,
  sections TEXT NOT NULL,
  permissions TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  created_at VARCHAR(32) NOT NULL,
  updated_at VARCHAR(32) NOT NULL,
  UNIQUE(workspace_id,slug),
  FOREIGN KEY(workspace_id) REFERENCES workspaces(id)
);

CREATE TABLE IF NOT EXISTS employee_profiles (
  workspace_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  employee_id VARCHAR(40) NOT NULL,
  team_id VARCHAR(64) NOT NULL,
  team_role VARCHAR(20) NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  PRIMARY KEY(workspace_id,user_id),
  UNIQUE(workspace_id,employee_id),
  FOREIGN KEY(workspace_id,user_id) REFERENCES memberships(workspace_id,user_id),
  FOREIGN KEY(team_id) REFERENCES organization_teams(id)
);

CREATE TABLE IF NOT EXISTS employee_invites (
  invite_id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  employee_id VARCHAR(40) NOT NULL,
  team_id VARCHAR(64) NOT NULL,
  team_role VARCHAR(20) NOT NULL,
  FOREIGN KEY(invite_id) REFERENCES invites(id),
  FOREIGN KEY(team_id) REFERENCES organization_teams(id)
);

CREATE TABLE IF NOT EXISTS organization_work (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  team_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64),
  kind VARCHAR(20) NOT NULL,
  title VARCHAR(200) NOT NULL,
  content TEXT NOT NULL,
  state VARCHAR(20) NOT NULL,
  owner_id VARCHAR(64) NOT NULL,
  due_date VARCHAR(32) NOT NULL,
  version_tag VARCHAR(60) NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  created_by VARCHAR(64) NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  updated_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(team_id) REFERENCES organization_teams(id),
  FOREIGN KEY(project_id) REFERENCES projects(id),
  FOREIGN KEY(owner_id) REFERENCES users(id),
  FOREIGN KEY(created_by) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS organization_work_issues (
  work_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  PRIMARY KEY(work_id,issue_id),
  FOREIGN KEY(work_id) REFERENCES organization_work(id),
  FOREIGN KEY(issue_id) REFERENCES issues(id)
);

CREATE TABLE IF NOT EXISTS project_team_settings (
  project_id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  FOREIGN KEY(project_id) REFERENCES projects(id),
  FOREIGN KEY(workspace_id) REFERENCES workspaces(id)
);

CREATE TABLE IF NOT EXISTS project_team_assignments (
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64) NOT NULL,
  team_id VARCHAR(64) NOT NULL,
  PRIMARY KEY(project_id,team_id),
  FOREIGN KEY(project_id) REFERENCES projects(id),
  FOREIGN KEY(team_id) REFERENCES organization_teams(id),
  FOREIGN KEY(workspace_id) REFERENCES workspaces(id)
);

CREATE TABLE IF NOT EXISTS home_events (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  actor_id VARCHAR(64) NOT NULL,
  action VARCHAR(100) NOT NULL,
  entity_type VARCHAR(32) NOT NULL,
  entity_id VARCHAR(64) NOT NULL,
  title VARCHAR(255) NOT NULL,
  project_id VARCHAR(64),
  team_id VARCHAR(64),
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(workspace_id) REFERENCES workspaces(id),
  FOREIGN KEY(actor_id) REFERENCES users(id)
);

CREATE INDEX IF NOT EXISTS issues_workspace_project ON issues (workspace_id,project_id,deleted_at);
CREATE INDEX IF NOT EXISTS issues_assignee ON issues (workspace_id,assignee_id);
CREATE INDEX IF NOT EXISTS issues_sprint ON issues (sprint_id,status_id);
CREATE INDEX IF NOT EXISTS history_workspace_created ON history (workspace_id,created_at);
CREATE INDEX IF NOT EXISTS notifications_user ON notifications (workspace_id,user_id,read_at);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions (expires_at);
CREATE INDEX IF NOT EXISTS modules_workspace_project ON project_modules (workspace_id,project_id,archived_at);
CREATE INDEX IF NOT EXISTS module_issues_issue ON module_issues (workspace_id,issue_id);
CREATE INDEX IF NOT EXISTS planning_baselines_project ON planning_baselines (workspace_id,project_id);
CREATE INDEX IF NOT EXISTS sprint_snapshots_workspace ON sprint_snapshots (workspace_id,sprint_id);
CREATE INDEX IF NOT EXISTS account_tokens_user ON account_tokens (user_id,purpose,expires_at);
CREATE INDEX IF NOT EXISTS deliveries_user ON mail_deliveries (user_id,created_at);
CREATE INDEX IF NOT EXISTS issue_templates_workspace ON issue_templates (workspace_id,project_id);
CREATE INDEX IF NOT EXISTS employee_team ON employee_profiles (workspace_id,team_id);
CREATE INDEX IF NOT EXISTS organization_work_team ON organization_work (workspace_id,team_id,kind,state);
CREATE INDEX IF NOT EXISTS home_events_cursor ON home_events (workspace_id,created_at,id);
CREATE INDEX IF NOT EXISTS home_events_team ON home_events (workspace_id,team_id,created_at);
CREATE INDEX IF NOT EXISTS home_events_actor ON home_events (workspace_id,actor_id,action,created_at);
CREATE INDEX IF NOT EXISTS project_teams_team ON project_team_assignments (workspace_id,team_id,project_id);
